type Stack struct {
	items []int
}

func (s *Stack) Push(v int) {
	s.items = append(s.items, v)
}

func (s *Stack) Pop() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	last := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return last, true
}

func main() {
	var s Stack
	s.Push(1)
	s.Push(2)
	s.Push(3)

	for i := 0; i < 4; i++ {
		v, ok := s.Pop()
		fmt.Println(v, ok)
	}
}

